// === Tab: mySketch.js ===
let mic, fft;
let particles = [];
const numParticles = 4000;
let zOffset = 0;

function setup() {
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100, 100);
  mic = new p5.AudioIn();
  mic.start();
  fft = new p5.FFT(0.9, 1024);
  fft.setInput(mic);

  for (let i = 0; i < numParticles; i++) {
    particles.push(new Particle());
  }
}

function draw() {
  background(0, 0, 0, 5);
  let spectrum = fft.analyze();
  let subBass = fft.getEnergy(20, 60);
  let bass = fft.getEnergy(60, 250);
  let mid = fft.getEnergy(250, 2000);
  let treble = fft.getEnergy(2000, 6000);
  let presence = fft.getEnergy(6000, 12000);

  zOffset += 0.01;

  for (let p of particles) {
    p.update(subBass, bass, mid, treble, presence);
    p.display();
  }
}

class Particle {
  constructor() {
    this.init();
  }

  init() {
    this.pos = createVector(random(width), random(height));
    this.vel = createVector(0, 0);
    this.hue = random(360);
    this.type = floor(random(5));
    this.alpha = 100;
    this.brightness = 40;
  }

  update(sub, bass, mid, treble, presence) {
    // ノイズベースの流体的な動き
    let n = noise(this.pos.x * 0.002, this.pos.y * 0.002, zOffset);
    let angle = TAU * n;
    let force = p5.Vector.fromAngle(angle);
    force.mult(0.5);
    this.vel.add(force);
    this.vel.limit(2);
    this.pos.add(this.vel);

    // サウンドに応じた変化
    let amp;
    switch (this.type) {
      case 0:
        amp = sub;
        this.hue = 230; // 青
        break;
      case 1:
        amp = bass;
        this.hue = 180; // シアン
        break;
      case 2:
        amp = mid;
        this.hue = 120; // 緑
        break;
      case 3:
        amp = treble;
        this.hue = 60; // 黄
        break;
      case 4:
        amp = presence;
        this.hue = 330; // ピンク
        break;
    }

    let speedBoost = map(amp, 0, 255, 0.5, 3);
    this.vel.mult(speedBoost);
    this.alpha = map(amp, 0, 255, 20, 100);
    this.brightness = map(amp, 0, 255, 10, 100); // 👈 明度の変化を追加

    // 画面外に出たら戻す
    if (this.pos.x < -50 || this.pos.x > width + 50 || this.pos.y < -50 || this.pos.y > height + 50) {
      this.init();
    }
  }

  display() {
    noStroke();
    fill(this.hue, 80, this.brightness, this.alpha); // 👈 明度に応じた色
    ellipse(this.pos.x, this.pos.y, 4, 4);
  }
}

